; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti83 (TI-83 Plus / 84 Plus (TI-OS)), starts in normal mode
; ============================================================

			org #9D95

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, ntc_ti_stack		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; Main.bas 4: n = 42
			dw kw_ltov, 42, var_n

			; Main.bas 5: Print "hello"; n, "x"
			dw kw_printstrvar, str0
			dw kw_printint, var_n
			dw kw_printstrvar, str1
			dw kw_printnl

			; Main.bas 6: Cls
			dw kw_cls

			; Main.bas 7: Locate 3, 4
			dw kw_locatell, 3, 4

			; Main.bas 8: Input "name"; s
			dw kw_printstrvar, str2
			dw kw_inputstr, var_s

			; Main.bas 9: Print s
			dw kw_printstrvar, var_s
			dw kw_printnl

			; Main.bas 10: k$ = Inkey$
			dw kw_inkeys, stmp0
			dw kw_strcpy, var_k, stmp0

			; Main.bas 11: Print k$; Inkey
			dw kw_printstrvar, var_k
			dw kw_inkey, tmp0
			dw kw_printint, tmp0
			dw kw_printnl

			; Main.bas 12: Input "num"; n
			dw kw_printstrvar, str3
			dw kw_inputint, var_n

			; Main.bas 13: Print n + 1
			dw kw_addl, var_n, 1, tmp0
			dw kw_printint, tmp0
			dw kw_printnl

			; Main.bas 14: Print "lines "; StdIO.Lines
			dw kw_printstrvar, str4
			dw kw_printint, var_stdio_lines
			dw kw_printnl
			dw kw_printnl0
			dw kw_printstrvar, str5
			dw kw_waitkey
			dw kw_stop

; ============================================================
; Variables
; ============================================================

var_n:			dw 0
			db 40			; capacity
var_s:			ds 41
			db 40			; capacity
var_k:			ds 41
var_stdio_lines:			dw 0
tmp0:			dw 0
			db 40			; capacity
stmp0:			ds 41

; ============================================================
; Strings
; ============================================================

str0:			db "hello", 0
str1:			db " x", 0
str2:			db "name? ", 0
str3:			db "num? ", 0
str4:			db "lines ", 0
str5:			db "Press a key", 0
str6:			db "<", 0
str7:			db ">", 0
str8:			db "? ", 0
str9:			db "!", 0
str10:			db "[cls]", 0
str11:			db "[at ", 0
str12:			db ",", 0
str13:			db "]", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_icnt @data
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_iptr @data
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done

;## ntc_d_ivar @data
ntc_ivar:		dw 0			; inputint / inkey: dest var

;## ntc_d_aptr @data
ntc_aptr:		dw 0			; atoi: text pointer

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## ntc_d_inbuf @data
				db 40			; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_gets ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and DEL (or backspace). HL = buffer (its capacity in the byte
; before it), DE = where to
; jp when done (after the newline). 40 chars max, 0 terminated.
ntc_gets:
			ld (ntc_iptr), hl
			ld (ntc_ilink), de
			dec hl
			ld a, (hl)			; the buffer's capacity
			ld (ntc_icap), a
			xor a
			ld (ntc_icnt), a
ntc_gs_wait:
			ld ix, ntc_gs_key
			jp ntc_plat_getkey
ntc_gs_key:
			cp 13
			jr z, ntc_gs_done
			cp 127
			jr z, ntc_gs_del
			cp 8
			jr z, ntc_gs_del
			cp 32
			jr c, ntc_gs_wait
			ld c, a
			ld a, (ntc_icap)
			ld b, a
			ld a, (ntc_icnt)
			cp b
			jr nc, ntc_gs_wait
			inc a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			ld (hl), c
			inc hl
			ld (ntc_iptr), hl
			ld a, c
			ld ix, ntc_gs_wait
			jp ntc_plat_putc
ntc_gs_del:
			ld a, (ntc_icnt)
			or a
			jr z, ntc_gs_wait
			dec a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			dec hl
			ld (ntc_iptr), hl
			ld ix, ntc_gs_wait
			jp ntc_plat_backspace
ntc_gs_done:
			ld hl, (ntc_iptr)
			ld (hl), 0
			ld ix, (ntc_ilink)
			jp ntc_plat_newline

;## kw_inputstr ntc_gets
;kw_inputstr, <straddr>
kw_inputstr:
			pop hl
			ld de, ntc_next
			jp ntc_gets

;## kw_inputint ntc_gets ntc_atoi
;kw_inputint, <var>  - signed decimal, stops at the first non digit
kw_inputint:
			pop hl
			ld (ntc_ivar), hl
			ld hl, ntc_inbuf
			ld de, ntc_atoi
			jp ntc_gets

;## ntc_atoi ntc_data
; text to number into the var at (ntc_ivar). ntc_atoi reads ntc_inbuf,
; ntc_atoi_hl reads HL. Spaces first, then - , then digits (or &H hex).
ntc_atoi:
			ld hl, ntc_inbuf
ntc_atoi_hl:
			ld a, (hl)
			cp ' '
			jr nz, ntc_atoi_sign
			inc hl
			jr ntc_atoi_hl
ntc_atoi_sign:
			ld c, 0
			cp '-'
			jr nz, ntc_atoi_amp
			inc c
			inc hl
			ld a, (hl)
ntc_atoi_amp:
			ld de, 0
			cp '&'
			jr nz, ntc_atoi_loop
			inc hl
			ld a, (hl)
			or #20
			cp 'h'
			jr nz, ntc_atoi_done
			inc hl
ntc_atoi_hex:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr c, ntc_atoi_hd
			or #20
			sub 'a' - '0'
			jr c, ntc_atoi_done
			cp 6
			jr nc, ntc_atoi_done
			add a, 10
ntc_atoi_hd:
			ex de, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			or l
			ld l, a
			ex de, hl
			inc hl
			jr ntc_atoi_hex
ntc_atoi_loop:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr nc, ntc_atoi_done
			ld (ntc_aptr), hl
			ex de, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de
			add hl, hl
			ld e, a
			ld d, 0
			add hl, de
			ex de, hl
			ld hl, (ntc_aptr)
			inc hl
			jr ntc_atoi_loop
ntc_atoi_done:
			ld a, c
			or a
			jr z, ntc_atoi_store
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_atoi_store:
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got
			jp ntc_plat_scankey
ntc_inkey_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_inkeys ntc_data ntc_plat_key
;kw_inkeys, <dest>  - Inkey$: the new key press as a string, "" if none
kw_inkeys:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inks_got
			jp ntc_plat_scankey
ntc_inks_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			or a
			ret z
			inc hl
			ld (hl), 0
			ret

;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

;## kw_locatell ntc_data ntc_plat_screen
;kw_locatell, <x>, <y>  - 1 based
kw_locatell:
			pop bc
			pop de
			ld h, c
			ld l, e
			ld ix, ntc_next
			jp ntc_plat_locate

;## ntc_plat_data
; ------------------------------------------------------------
; TI-OS bcall equates - standard ti83plus.inc values.  ;!!TI confirm every one
; against your ti83plus.inc (the include can't be downloaded in this box).
; ------------------------------------------------------------
_PutC            equ #4504   ; A = char at cursor, advance curCol            ;!!TI
_PutS            equ #450A   ; HL = zero-terminated string                   ;!!TI
_NewLine         equ #452E   ; CR+LF, scroll if needed                       ;!!TI
_ClrLCDFull      equ #4540   ; clear the whole LCD                           ;!!TI
_HomeUp          equ #4558   ; curRow = curCol = 0                           ;!!TI
_GetCSC          equ #4018   ; A = scan code (0 = none), non-blocking        ;!!TI
_GetKey          equ #4972   ; A = key code, blocking (2nd/alpha handled)    ;!!TI
_JForceCmdNoChar equ #4027   ; clean return to the homescreen (exit)         ;!!TI
curRow           equ #844B   ; OS text cursor row  (0-7)                     ;!!TI
curCol           equ #844C   ; OS text cursor col  (0-15)                    ;!!TI

ntc_curx:		db 0			; column mirror (0 based) - counted for Tab
ntc_cury:		db 0			; row mirror (0 based)
ntc_scols:		db 16			; columns (large-font grid)                 ;!!TI
ntc_ti_stack	equ ntc_end + 256	; the real stack: the 256 bytes above the program image.
									; SP is swapped to it only for a bcall (which is shallow).

;## ntc_ti_call ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_ti_call - IY = a real-stack routine (it may bcall). SP is the thread;
; swap it to the real stack (ntc_csp), call the routine, swap back, keep IX.
; This is the MSX ntc_vcall pattern retargeted to TI-OS. Registers pass
; straight through to/from the routine (A = char for putc, A = key out, ...).
; ------------------------------------------------------------
ntc_ti_call:
			ld (ntc_tiix), ix
			ld (ntc_tisp), sp
			ld sp, (ntc_csp)
			call ntc_ti_call_jp
			ld sp, (ntc_tisp)
			ld ix, (ntc_tiix)
			jp (ix)
ntc_ti_call_jp:
			jp (iy)
ntc_tiix:		dw 0			; IX over the call
ntc_tisp:		dw 0			; the thread's SP over the call

;## ntc_plat_screen ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_putc - A = character to the screen (_PutC), mirror curCol into ntc_curx
ntc_plat_putc:
			ld iy, ntc_tir_putc
			jp ntc_ti_call
ntc_tir_putc:
			rst #28
			dw _PutC				; A = char; OS advances/wraps curCol
			ld a, (curCol)
			ld (ntc_curx), a
			ret

; ntc_plat_newline - _NewLine, then curx mirror = 0
ntc_plat_newline:
			ld iy, ntc_tir_newline
			jp ntc_ti_call
ntc_tir_newline:
			rst #28
			dw _NewLine
			xor a
			ld (ntc_curx), a
			ret

;## ntc_plat_backspace @unit ntc_plat_screen ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_backspace - back up a column, blank it, back up again (large font)
ntc_plat_backspace:
			ld iy, ntc_tir_bs
			jp ntc_ti_call
ntc_tir_bs:
			ld a, (curCol)
			or a
			ret z					; already at column 0: nothing
			dec a
			ld (curCol), a			; step back
			ld a, ' '
			rst #28
			dw _PutC				; blank the cell (advances curCol again)
			ld a, (curCol)
			or a
			ret z
			dec a
			ld (curCol), a			; step back over the blank
			ld (ntc_curx), a
			ret

;## ntc_plat_cls @unit ntc_plat_screen ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_cls - clear the LCD and home the cursor
ntc_plat_cls:
			ld iy, ntc_tir_cls
			jp ntc_ti_call
ntc_tir_cls:
			rst #28
			dw _ClrLCDFull
			rst #28
			dw _HomeUp
			xor a
			ld (ntc_curx), a
			ret

;## ntc_plat_locate @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_locate - H = column, L = row, 1 based. curRow/curCol are OS RAM:
; writeable without a real stack, so no bcall / no SP swap needed.
ntc_plat_locate:
			ld a, h
			dec a
			ld (curCol), a
			ld (ntc_curx), a
			ld a, l
			dec a
			ld (curRow), a
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_key ntc_ti_call ntc_data
; ntc_plat_scankey - A = key or 0 (non-blocking, _GetCSC).
; ;!!TI _GetCSC returns a TI SCAN CODE (skEnter, sk0..., skGraph), NOT ASCII.
; A scancode->ASCII map (below, stubbed) is needed before Inkey reads sanely.
ntc_plat_scankey:
			ld iy, ntc_tir_scan
			jp ntc_ti_call
ntc_tir_scan:
			rst #28
			dw _GetCSC				; A = scan code or 0
			; ;!!TI map A (scan code) -> ASCII here; raw code passed through for now
			ret

; ntc_plat_getkey - wait for a key (poll _GetCSC so interrupts aren't required)
ntc_plat_getkey:
			ld iy, ntc_tir_getk
			jp ntc_ti_call
ntc_tir_getk:
			rst #28
			dw _GetCSC
			or a
			jr z, ntc_tir_getk
			; ;!!TI map A (scan code) -> ASCII here too
			ret

;## ntc_plat_exit ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_exit - clean return to the homescreen. SP is the mangled thread, so
; a plain ret can't go back; _JForceCmdNoChar resets the OS to the homescreen
; regardless of the stack. Swap to the real stack first.
ntc_plat_exit:
			ld sp, (ntc_csp)
			rst #28
			dw _JForceCmdNoChar		; does not return
			ret						; (unreached)                            ;!!TI


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
